module tb_TopModule;
    logic mode;
    logic too_cold;
    logic too_hot;
    logic fan_on;
    logic heater;
    logic aircon;
    logic fan;

    TopModule uut (
        .mode(mode),
        .too_cold(too_cold),
        .too_hot(too_hot),
        .fan_on(fan_on),
        .heater(heater),
        .aircon(aircon),
        .fan(fan)
    );

    initial begin
        integer i;
        for (i = 0; i < 16; i = i + 1) {
            {mode, too_cold, too_hot, fan_on} = i[3:0];
            #1;
            // Expected values
            // heater = mode & too_cold
            // aircon = ~mode & too_hot
            // fan = heater | aircon | fan_on
            logic exp_heater, exp_aircon, exp_fan;
            exp_heater = mode & too_cold;
            exp_aircon = ~mode & too_hot;
            exp_fan    = exp_heater | exp_aircon | fan_on;

            if (heater !== exp_heater || aircon !== exp_aircon || fan !== exp_fan) begin
                $display("SELFTEST FAIL: mode=%b too_cold=%b too_hot=%b fan_on=%b | got heater=%b aircon=%b fan=%b | expected heater=%b aircon=%b fan=%b",
                    mode, too_cold, too_hot, fan_on, heater, aircon, fan, exp_heater, exp_aircon, exp_fan);
                $finish;
            end
        }
        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
